from pathlib import Path
import base64, zlib

ROOT=Path('.')
def d(s): return zlib.decompress(base64.b64decode(s)).decode()
def rb(text,start,end,repl,label):
    a=text.find(start); b=text.find(end,a if a>=0 else 0)
    if a<0 or b<0: raise RuntimeError(f'{label} markers not found')
    return text[:a]+repl.rstrip()+'\n\n'+text[b:]

P={
'simple_post_card':'','simple_poll':'','simple_app_menu':'','simple_profile_header':'','simple_menu_section':'','simple_theme_toggle':'','simple_menu_item':'','simple_home_header':'','simple_top_tabs':'','simple_bottom':'',
}

post=ROOT/'app/src/main/java/com/example/ui/components/PostCard.kt'
t=post.read_text()
t=rb(t,'@Composable\nfun PostCard(','@Composable\nprivate fun PremiumPollCard(',d(P['simple_post_card']),'PostCard')
t=rb(t,'@Composable\nprivate fun PremiumPollCard(','@Composable\nprivate fun RowScope.ReadOnlyMetricAction(',d(P['simple_poll']),'Poll')
post.write_text(t)

menu=ROOT/'app/src/main/java/com/example/ui/components/AppMenuSheet.kt'
t=menu.read_text()
t=rb(t,'@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun AppMenuSheet(','@Composable\nprivate fun ProfileHeaderCard(',d(P['simple_app_menu']),'AppMenuSheet')
t=rb(t,'@Composable\nprivate fun ProfileHeaderCard(','@Composable\nprivate fun MenuSection(',d(P['simple_profile_header']),'ProfileHeader')
t=rb(t,'@Composable\nprivate fun MenuSection(','@Composable\nprivate fun ThemeToggleRow(',d(P['simple_menu_section']),'MenuSection')
t=rb(t,'@Composable\nprivate fun ThemeToggleRow(','@Composable\nprivate fun MenuItemRow(',d(P['simple_theme_toggle']),'ThemeToggle')
a=t.find('@Composable\nprivate fun MenuItemRow(')
if a<0: raise RuntimeError('MenuItemRow marker not found')
t=t[:a]+d(P['simple_menu_item']).rstrip()+'\n'
menu.write_text(t)

feed=ROOT/'app/src/main/java/com/example/ui/screens/FeedScreen.kt'
t=feed.read_text()
t=t.replace('contentPadding = PaddingValues(bottom = 92.dp)','contentPadding = PaddingValues(bottom = 72.dp)')
t=t.replace('.padding(end = 20.dp, bottom = 92.dp)','.padding(end = 16.dp, bottom = 74.dp)')
old='''                                        hasActiveStory = hasActiveStory
                                    )
                                    Spacer(Modifier.height(8.dp))
                                }'''
new='''                                        hasActiveStory = hasActiveStory
                                    )
                                    Spacer(
                                        Modifier
                                            .fillMaxWidth()
                                            .height(7.dp)
                                            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = .55f))
                                    )
                                }'''
if old not in t: raise RuntimeError('feed post spacing block not found')
t=t.replace(old,new,1)
t=rb(t,'@Composable\nprivate fun HomeHeader(','@Composable\nprivate fun TopNavigation(',d(P['simple_home_header']),'HomeHeader')
t=rb(t,'@Composable\nprivate fun TopIconTab(','@Composable\nprivate fun FeedRefreshingBanner(',d(P['simple_top_tabs']),'TopTabs')
feed.write_text(t)

bottom=ROOT/'app/src/main/java/com/example/ui/components/FloatingBottomBar.kt'
t=bottom.read_text()
t=rb(t,'@Composable\nfun FeedBottomBar(','/** Compatibility wrapper for older callers; new main navigation uses [FeedBottomBar]. */',d(P['simple_bottom']),'BottomBar')
bottom.write_text(t)
print('Applied simple Facebook-style feed/menu/navigation UI.')
